contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We allow depositing ether into this test contract before calling run
    // so that it can forward exactly 1 ether to c.lockInGuess.
    function run(bytes32 hash, uint sendAmount, bool doSettle) public payable {
        // Precondition: sendAmount is either 0 or exactly 1 ether. If it's 1 ether,
        // we must have that this contract has enough balance to forward it.
        require(sendAmount == 0 || sendAmount == 1 ether, "amount must be 0 or 1 ether");
        if (sendAmount == 1 ether) {
            require(address(this).balance >= 1 ether, "insufficient balance to forward");
        }

        // Record balances before interaction
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Try to call lockInGuess with exactly sendAmount forwarded (0 or 1 ether)
        bool lockedReverted;
        try c.lockInGuess{value: sendAmount}(hash) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Observe public getter for guesses[msg.sender]
        // The autogenerated getter for mapping(address => guess) guesses is guesses(address)
        // which returns (uint block, bytes32 guess).
        (uint gblock, bytes32 ghash) = c.guesses(address(this));

        // Optionally attempt to call settle and observe whether it reverts and final balances
        bool settledReverted = false;
        if (doSettle) {
            try c.settle() {
                settledReverted = false;
            } catch {
                settledReverted = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule asserted:
        // 1) If lockInGuess reverted, then nothing changed: stored guess must remain empty (block==0 and guess==0)
        //    and contract/test balances unchanged.
        // 2) If lockInGuess succeeded and we forwarded 1 ether, then the contract balance increased by 1 ether,
        //    and the stored guess for this address has block != 0 and guess == hash.
        // 3) If settle was attempted, then total Ether between this test and contract is conserved
        //    (i.e., afterC + afterThis == beforeC + beforeThis) regardless of settle reverting or not.
        assert(
            (
                lockedReverted
                ? (gblock == 0 && ghash == bytes32(0) && afterC == beforeC && afterThis == beforeThis)
                : (
                    // lockInGuess succeeded
                    (sendAmount == 1 ether && afterC == beforeC + 1 ether && gblock != 0 && ghash == hash)
                    ||
                    // or it succeeded with 0 value forwarded (no balance change) but still recorded a guess
                    (sendAmount == 0 && afterC == beforeC && gblock != 0 && ghash == hash)
                  )
            )
            &&
            // Ether conservation when settle attempted
            (!doSettle || (afterC + afterThis == beforeC + beforeThis))
        );
    }

    // Allow receiving ether when settle pays out
    receive() external payable {}
}

