contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will lock a guess and then call settle; amount must be exactly 1 ether to lock.
    function run(bytes32 hash, uint lockAmount) public payable {
        require(lockAmount == 1 ether);
        // Ensure this contract has enough balance to send lockAmount
        require(address(this).balance >= lockAmount);

        // Initially read contract balance and our balance
        uint256 beforeC = address(c).balance;
        uint256 beforeMe = address(this).balance;

        // Call lockInGuess sending exactly 1 ether
        c.lockInGuess{value: lockAmount}(hash);

        // After locking, the contract should have increased by 1 ether
        uint256 afterLockC = address(c).balance;
        // Now attempt to settle and catch whether it reverted
        bool didRevert;
        try c.settle() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterSettleC = address(c).balance;
        uint256 afterSettleMe = address(this).balance;

        // Read the guess mapping for this contract (auto-generated getter: guesses)
        // The getter has signature guesses(address) returns (uint256, bytes32) because struct fields
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // General property (single assert):
        // If settle reverted, then the stored block may remain nonzero; if settle didn't revert,
        // then storedBlock must be 0. Moreover, if settle didn't revert and our balance increased by 2 ether,
        // then the contract's balance decreased by 2 ether and the stored slot is cleared; otherwise if no payout
        // happened then balances reflect no payout and stored slot is cleared.
        assert(
            // settle did revert: we only require that contract balance after lock is at least before + 1
            (didRevert && afterLockC >= beforeC + 1)
            ||
            // settle did not revert: stored slot cleared
            (!didRevert && storedBlock == 0 && (
                // either we received a 2 ether payout (our balance increased by 2) and c decreased by 2
                ((afterSettleMe == beforeMe + 2 ether) && (afterSettleC + 2 ether == beforeC + 1))
                // or we did not receive payout and balances reflect only the earlier lock (c kept the funds)
                || ((afterSettleMe == beforeMe) && (afterSettleC == beforeC + 1))
            ))
        );
    }

    // Allow receiving Ether in case settle transfers to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will lock a guess and then call settle; must send exactly 1 ether to lock.
    // Parameters: hash to lock, and amount to send for lock (must be 1 ether).
    function run(bytes32 hash, uint lockAmount) public payable {
        require(lockAmount == 1 ether);
        require(address(this).balance >= lockAmount);

        // record balances before any interaction
        uint256 beforeC = address(c).balance;
        uint256 beforeMe = address(this).balance;

        // Lock a guess by sending exactly 1 ether
        c.lockInGuess{value: lockAmount}(hash);

        // Balance after locking
        uint256 afterLockC = address(c).balance;
        uint256 afterLockMe = address(this).balance;

        // Now attempt to settle and record whether it reverted
        bool didRevert;
        try c.settle() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Balances after settle attempt
        uint256 afterSettleC = address(c).balance;
        uint256 afterSettleMe = address(this).balance;

        // The contract exposes no direct getter for the internal mapping 'guesses'.
        // But the intended invariant: if settle succeeded (did not revert), the mapping slot for this address
        // should have been cleared (block == 0). We cannot read it directly, so we instead observe the
        // economic effects: if settle succeeded and paid out, caller receives 2 ether and c loses 2 ether;
        // if settle succeeded but did not pay (answer==0 or mismatch), then caller balance stays as afterLockMe
        // and c keeps the locked ether. If settle reverted, the contract must at least keep the locked ether.

        // Single general assert combining these observations:
        assert(
            // Case: settle reverted -> contract must have kept at least the locked ether (i.e. increased by >= 1)
            (didRevert && afterSettleC >= beforeC + 1)
            ||
            // Case: settle did not revert -> the mapping slot was cleared and balances reflect either a payout of 2 ether
            // or no payout (only the lock). We express this by checking balance deltas.
            (!didRevert && (
                // payout occurred: our balance increased by 2 and contract decreased by 2 relative to after lock
                ((afterSettleMe == afterLockMe + 2 ether) && (afterSettleC + 2 ether == afterLockC))
                // or no payout: balances unchanged since after lock (contract still holds the locked ether)
                || ((afterSettleMe == afterLockMe) && (afterSettleC == afterLockC))
            ))
        );
    }

    // allow receiving Ether in case settle transfers to this contract
    receive() external payable {}
}

