    // params: hash to lock, amount to send for lock (must be exactly 1 ether)
    function run(bytes32 h, uint lockAmount) public payable {
        require(lockAmount == 1 ether);
        require(address(this).balance >= lockAmount);

        // record contract balance before locking
        uint256 beforeC = address(c).balance;

        // perform the lockInGuess call (top-level; may revert if preconditions fail)
        c.lockInGuess{value: lockAmount}(h);

        // after successful lock, the contract balance must have increased by exactly 1 ether
        uint256 afterLockC = address(c).balance;

        // read the stored guess.slot for this contract via the public getter: guesses is not public, but struct isn't exposed.
        // However, C has no public getter for guesses; we can observe that lockInGuess sets guesses[msg.sender].block != 0
        // and that settle clears it. To check stored block we must call settle in a way that doesn't necessarily revert.
        // So we first attempt to call settle and observe whether it reverts. If it does not revert, then after it the stored block should be zero.

        bool settledReverted;
        // try calling settle; it may revert if block.number <= locked block
        try c.settle() {
            settledReverted = false;
        } catch {
            settledReverted = true;
        }

        // If settle did not revert, then it must have cleared the stored slot (block == 0). We cannot read block directly, but calling settle again now must revert because guesses[msg.sender].block == 0 and settle requires it nonzero.
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }

        // General invariant:
        // 1) afterLockC == beforeC + 1 ether (the lock increased contract balance by 1 ether), and
        // 2) if the first settle call did not revert, then a subsequent settle must revert (because the stored block was cleared to 0);
        //    otherwise (first settle reverted) we make no requirement about the second settle's behavior.
        assert(afterLockC == beforeC + 1 ether && (settledReverted || secondSettleReverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: hash to lock; must send exactly 1 ether as lockAmount
    function run(bytes32 h, uint lockAmount) public payable {
        require(lockAmount == 1 ether);
        require(address(this).balance >= lockAmount + 2 ether);

        // record balances before any interaction
        uint balCTestBefore = address(c).balance;
        uint balThisBefore = address(this).balance;

        // perform lockInGuess with exactly 1 ether; this must succeed for the meaningful rule to apply
        c.lockInGuess{value: lockAmount}(h);

        // after successful lock, contract balance increased by 1 ether
        uint balCTestAfterLock = address(c).balance;

        // try to call settle; it may revert (if block.number <= locked block) or succeed
        bool firstSettleReverted;
        try c.settle() {
            firstSettleReverted = false;
        } catch {
            firstSettleReverted = true;
        }

        // read balances after the first settle attempt
        uint balCTestAfterSettle = address(c).balance;
        uint balThisAfterSettle = address(this).balance;

        // If firstSettleReverted is false, then settle executed. After a successful settle the guess for this address must be cleared
        // We cannot directly read the guess, but a second call to settle must revert because settle requires guesses[msg.sender].block != 0.
        bool secondSettleReverted;
        if (!firstSettleReverted) {
            try c.settle() {
                secondSettleReverted = false;
            } catch {
                secondSettleReverted = true;
            }
        } else {
            // if first settle reverted we won't require any behavior of second settle; mark as true to not force payout branch
            secondSettleReverted = true;
        }

        // General rule asserted:
        // 1) The initial lock increased c's balance by exactly 1 ether.
        // 2) If the first settle call succeeded (firstSettleReverted == false) then the stored guess was cleared (secondSettleReverted == true),
        //    and either (a) the caller received 2 ether (its balance increased by exactly 2 ether) and c's balance decreased by 2 ether,
        //    or (b) the caller did not receive 2 ether (its balance did not increase by 2) and c's balance did not decrease by 2.
        // This captures that settle either pays out correctly or doesn't pay out, but in either successful-settle case it clears the guess.
        assert(
            // lock changed c balance by +1 ether
            balCTestAfterLock == balCTestBefore + 1 ether
            && (
                // if first settle reverted, we only require the lock effect
                firstSettleReverted
                || (
                    // first settle succeeded: guess cleared (second settle must revert)
                    (!firstSettleReverted && secondSettleReverted
                        && (
                            // payout happened: this received exactly 2 ether and c lost exactly 2 ether
                            (balThisAfterSettle == balThisBefore + 2 ether && balCTestAfterSettle == balCTestAfterLock - 2 ether)
                            // or payout did not happen: balances unchanged except the prior lock
                            || (balThisAfterSettle == balThisBefore && balCTestAfterSettle == balCTestAfterLock)
                        )
                    )
                )
            )
        );
    }

    receive() external payable {}
}

